const menuButton=document.querySelector('.menu-toggle');const siteNav=document.querySelector('#site-nav');if(siteNav){const labels={'shirts.html':'The Drop','collections.html':'Collections','about.html':'The Story'};siteNav.querySelectorAll('a').forEach(link=>{const key=link.getAttribute('href');if(labels[key])link.textContent=labels[key]});const guideLink=siteNav.querySelector('a[href="guide.html"]');if(guideLink)guideLink.remove();if(!siteNav.querySelector('a[href="social.html"]')){const follow=document.createElement('a');follow.href='social.html';follow.textContent='Follow';follow.className='nav-cta';siteNav.appendChild(follow)}}if(menuButton&&siteNav){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));siteNav.classList.toggle('open',!open)});siteNav.addEventListener('click',()=>{menuButton.setAttribute('aria-expanded','false');siteNav.classList.remove('open')})}
document.querySelectorAll('.site-footer').forEach(footer=>{const copyright=footer.querySelector('.fine');if(copyright)copyright.textContent='© 2026 Low Value Content, an imprint of Nelson Grey LLC. All rights reserved.';const links=footer.querySelector('.footer-links');if(!links)return;const social=[...links.querySelectorAll('a[href*="social.html"]')];if(!social.length)return;const socialNav=document.createElement('nav');socialNav.className='social-links';socialNav.setAttribute('aria-label','Social media');social.forEach(link=>socialNav.appendChild(link));footer.insertBefore(socialNav,copyright)});
const reveals=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});reveals.forEach(element=>observer.observe(element))}else{reveals.forEach(element=>element.classList.add('visible'))}
